-- 202609110001_scorecard_takes_and_prediction_filter.sql
do $apply$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '202609110001') then
    execute $migration_202609110001$
-- Recreate expert_scorecards so the migrations path matches setup.sql.
--
-- Two integrity changes:
--   1. Filter the join to record_type = 'prediction'. Takes (soft, imputed
--      claims) must not enter total_predictions, open_predictions, accuracy,
--      Brier, or wilson_rank_score. Comments in code enforce this, but a
--      view without the filter still counted admin-approved takes on any
--      environment bootstrapped from migrations rather than setup.sql.
--   2. Add total_takes as a scalar subquery, so the expert page's "Takes"
--      tile has a real number instead of silently defaulting to zero.
--
-- The definition below is identical to setup.sql:329-392.

create or replace view public.expert_scorecards
with (security_invoker = true)
as
select
  e.id as expert_id,
  e.slug,
  e.display_name,
  e.x_handle,
  e.avatar_url,
  e.headline,
  e.primary_category_slug,
  count(p.id)::integer as total_predictions,
  count(p.id) filter (where p.status in ('open', 'due', 'resolution_pending'))::integer as open_predictions,
  count(r.id) filter (where r.outcome in ('correct', 'incorrect'))::integer as resolved_predictions,
  count(r.id) filter (where r.outcome = 'correct')::integer as correct_predictions,
  count(r.id) filter (where r.outcome = 'incorrect')::integer as incorrect_predictions,
  count(r.id) filter (where r.outcome = 'partial')::integer as partial_predictions,
  count(r.id) filter (where r.outcome = 'ambiguous')::integer as ambiguous_predictions,
  count(r.id) filter (where r.outcome = 'void')::integer as void_predictions,
  case when count(r.id) filter (where r.outcome in ('correct','incorrect')) > 0
    then count(r.id) filter (where r.outcome = 'correct')::numeric /
      count(r.id) filter (where r.outcome in ('correct','incorrect'))
    else null end as accuracy,
  case when count(r.id) filter (where r.outcome in ('correct','incorrect')) > 0 then
    greatest(0, (
      (count(r.id) filter (where r.outcome = 'correct')::numeric /
       count(r.id) filter (where r.outcome in ('correct','incorrect')) + 1.281551565545^2 /
       (2 * count(r.id) filter (where r.outcome in ('correct','incorrect')))) -
      1.281551565545 * sqrt((
        (count(r.id) filter (where r.outcome = 'correct')::numeric /
         count(r.id) filter (where r.outcome in ('correct','incorrect'))) *
        (1 - count(r.id) filter (where r.outcome = 'correct')::numeric /
         count(r.id) filter (where r.outcome in ('correct','incorrect'))) +
        1.281551565545^2 / (4 * count(r.id) filter (where r.outcome in ('correct','incorrect')))
      ) / count(r.id) filter (where r.outcome in ('correct','incorrect')))
    ) / (1 + 1.281551565545^2 /
      count(r.id) filter (where r.outcome in ('correct','incorrect'))))
    else null end as wilson_rank_score,
  count(r.id) filter (
    where r.outcome in ('correct','incorrect') and p.explicit_probability is not null
  )::integer as probabilistic_predictions,
  avg(power(p.explicit_probability - case when r.outcome = 'correct' then 1 else 0 end, 2))
    filter (where r.outcome in ('correct','incorrect') and p.explicit_probability is not null) as brier_score,
  count(r.id) filter (where r.outcome in ('correct','incorrect')) >= 5 as leaderboard_eligible,
  count(r.id) filter (where r.outcome in ('correct','incorrect')) < 20 as provisional,
  (select count(*)::integer from public.predictions t
     where t.expert_id = e.id and t.published_at is not null
       and t.status <> 'source_unavailable' and t.record_type = 'take') as total_takes
from public.experts e
left join public.predictions p on p.expert_id = e.id
  and p.published_at is not null and p.status <> 'source_unavailable'
  and p.record_type = 'prediction'
left join public.resolutions r on r.prediction_id = p.id and r.approved_at is not null
where e.is_active
group by e.id;

grant select on public.expert_scorecards to anon, authenticated;
$migration_202609110001$;
    insert into supabase_migrations.schema_migrations (version, name, statements) values ('202609110001', 'scorecard_takes_and_prediction_filter', '{}');
  end if;
end $apply$;

-- 202609110002_search_similarity_floor.sql
do $apply$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '202609110002') then
    execute $migration_202609110002$
-- Tighten the noise floor on global_search.
--
-- The previous definition only required the trigram % operator, which is
-- pg_trgm's default similarity threshold (0.3). Common tokens like "the"
-- or short queries pull long tails of low-signal matches that all end up
-- adjacent to the real hits under a `order by similarity desc` sort,
-- because the sort tolerates ties.
--
-- The new definition:
--   * Uses an explicit similarity(...) >= floor per branch instead of `%`,
--     so we can tune each surface independently (experts and topics are
--     tighter than predictions, which have longer text).
--   * Adds a final HAVING-style predicate on the composite score so a
--     match that only barely clears the floor doesn't outrank a strong
--     match on a different branch.
--   * Filters predictions and markets to record_type='prediction' /
--     public visibility. Takes never surface via search — same rule as
--     the leaderboard.

create or replace function public.global_search(search_query text, result_limit integer default 10)
returns table(result_type text, result_id text, title text, subtitle text, href text, score real)
language sql
stable
security invoker
as $$
  with q as (select trim(search_query) as value)
  select * from (
    select 'expert', e.id::text, e.display_name,
      case when e.x_handle is not null then '@' || e.x_handle else e.headline end,
      '/experts/' || e.slug,
      (case when lower(e.display_name) = lower(q.value) then 4 else 0 end +
       case when lower(coalesce(e.x_handle,'')) = lower(regexp_replace(q.value, '^@', '')) then 3 else 0 end +
       greatest(similarity(e.display_name, q.value), similarity(coalesce(e.x_handle,''), q.value)))::real
    from public.experts e cross join q
    where e.is_active
      and greatest(similarity(e.display_name, q.value), similarity(coalesce(e.x_handle,''), regexp_replace(q.value, '^@', ''))) >= 0.30
    union all
    select 'topic', t.id::text, t.title, c.name, '/topics/' || t.slug,
      (case when lower(t.title) = lower(q.value) then 3 else 0 end + similarity(t.title, q.value))::real
    from public.topics t cross join q left join public.categories c on c.slug = t.category_slug
    where t.status = 'active' and similarity(t.title, q.value) >= 0.28
    union all
    select 'prediction', p.id::text, p.normalized_claim, e.display_name, '/predictions/' || p.id,
      similarity(p.normalized_claim, q.value)::real
    from public.predictions p cross join q join public.experts e on e.id = p.expert_id
    where p.published_at is not null
      and p.status <> 'source_unavailable'
      and p.record_type = 'prediction'
      and similarity(p.normalized_claim, q.value) >= 0.22
    union all
    select 'market', m.id::text, m.question, 'Polymarket', '/topics/' || coalesce(t.slug, ''),
      similarity(m.question, q.value)::real
    from public.markets m cross join q left join public.topics t on t.id = m.topic_id
    where t.id is not null and similarity(m.question, q.value) >= 0.28
  ) results(result_type, result_id, title, subtitle, href, score)
  where results.score >= 0.30
  order by results.score desc
  limit greatest(1, least(result_limit, 25));
$$;

grant execute on function public.global_search(text, integer) to anon, authenticated;
$migration_202609110002$;
    insert into supabase_migrations.schema_migrations (version, name, statements) values ('202609110002', 'search_similarity_floor', '{}');
  end if;
end $apply$;

-- 202609110003_no_scoring_on_takes.sql
do $apply$ begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '202609110003') then
    execute $migration_202609110003$
-- DB-enforce "takes are never scored".
--
-- The rule lives in code comments (scripts/process-sources.ts, lib/data/
-- public.ts) and is trusted by the leaderboard math and the LLM auto-approver.
-- One stray admin action or a future refactor could violate it without any
-- validator noticing. Move the invariant into the database, where it holds
-- against every write path — CLI import, admin action, service-role update
-- outside the app entirely.
--
-- A CHECK constraint can't reference another table's column, so we use a
-- trigger. On insert/update of resolutions, if the referenced prediction has
-- record_type = 'take' AND scoring_eligible is true, raise. Also block the
-- reverse: a prediction that already has a scoring-eligible resolution can't
-- be re-typed to a take without first clearing the resolution.

create or replace function public.guard_take_never_scored()
returns trigger language plpgsql as $$
declare
  linked_record_type text;
begin
  if tg_table_name = 'resolutions' then
    if new.scoring_eligible then
      select p.record_type into linked_record_type
      from public.predictions p
      where p.id = new.prediction_id;
      if linked_record_type = 'take' then
        raise exception 'Takes cannot have scoring_eligible resolutions; downgrade the prediction or mark the resolution non-scoring.'
          using errcode = '23514';
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'predictions' then
    if new.record_type = 'take' and (old.record_type is distinct from 'take') then
      if exists (
        select 1 from public.resolutions r
        where r.prediction_id = new.id and r.scoring_eligible = true
      ) then
        raise exception 'Cannot re-type prediction to take while a scoring-eligible resolution exists.'
          using errcode = '23514';
      end if;
    end if;
    return new;
  end if;

  return new;
end;
$$;

drop trigger if exists resolutions_no_take_scoring on public.resolutions;
create trigger resolutions_no_take_scoring
before insert or update on public.resolutions
for each row execute function public.guard_take_never_scored();

drop trigger if exists predictions_no_retype_take on public.predictions;
create trigger predictions_no_retype_take
before update of record_type on public.predictions
for each row execute function public.guard_take_never_scored();
$migration_202609110003$;
    insert into supabase_migrations.schema_migrations (version, name, statements) values ('202609110003', 'no_scoring_on_takes', '{}');
  end if;
end $apply$;

